from __future__ import annotations

import re
from pathlib import Path

import pytest

_FORBIDDEN_PHRASES = (
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "comprehensive",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
)

_FORBIDDEN_EMOJI_RE = re.compile("[\U0001f300-\U0001faff]|" "[✀-➿]|" "[\U0001f000-\U0001ffff]")


_ALLOWED_FILES = {
    "tests/test_house_style.py",
    "docs/repo-plan.md",
}


_TEXT_SUFFIXES = (
    ".py",
    ".md",
    ".yaml",
    ".yml",
    ".toml",
    ".sh",
    ".txt",
    ".cfg",
    ".ini",
    ".dockerfile",
)


def _iter_text_files(root: Path):
    for path in root.rglob("*"):
        if not path.is_file():
            continue
        rel = path.relative_to(root).as_posix()
        if any(
            rel.startswith(skip)
            for skip in (
                ".git/",
                ".mypy_cache/",
                ".pytest_cache/",
                ".ruff_cache/",
                ".venv/",
                "build/",
                "dist/",
                "__pycache__",
                "checkpoints/",
                "runs/",
                "artifacts/",
            )
        ):
            continue
        if path.suffix.lower() in _TEXT_SUFFIXES or path.name in {"Dockerfile", "Makefile"}:
            yield rel, path


@pytest.mark.parametrize("phrase", _FORBIDDEN_PHRASES)
def test_no_phrase_anywhere(phrase: str, repo_root) -> None:
    needle = phrase.lower()
    offenders: list[str] = []
    for rel, path in _iter_text_files(repo_root):
        if rel in _ALLOWED_FILES:
            continue
        try:
            text = path.read_text(errors="ignore").lower()
        except OSError:
            continue
        if needle in text:
            offenders.append(rel)
    assert not offenders, f"forbidden phrase {phrase!r} found in: {offenders}"


def test_no_emoji_anywhere(repo_root) -> None:
    offenders: list[str] = []
    for rel, path in _iter_text_files(repo_root):
        if rel in _ALLOWED_FILES:
            continue
        try:
            text = path.read_text(errors="ignore")
        except OSError:
            continue
        if _FORBIDDEN_EMOJI_RE.search(text):
            offenders.append(rel)
    assert not offenders, f"emoji found in: {offenders}"
